3	import org.junit.jupiter.api.BeforeEach;
4	import org.junit.jupiter.api.Test;
5	import org.springframework.beans.factory.annotation.Autowired;
6	import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
7	import org.springframework.boot.test.context.SpringBootTest;
8	import org.springframework.http.MediaType;
9	import org.springframework.jdbc.core.JdbcTemplate;
10	import org.springframework.test.web.servlet.MockMvc;
11	
12	import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
13	
14	import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
15	import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
16	import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
17	
18	/**
19	 * 批量放行测试：原子整批拒绝及各项原因、重复放行 409、放行人校验、
20	 * 证书撤销后失去当前可用资格但历史保留、批次数量校验、历史明细与可用查询。
21	 */
22	@SpringBootTest
23	@AutoConfigureMockMvc
24	class ReleaseApiTest {
25	
26	    @Autowired
27	    private MockMvc mvc;
28	
29	    @Autowired
30	    private JdbcTemplate jdbc;
31	
32	    @BeforeEach
33	    void clean() {
34	        jdbc.update("DELETE FROM release_record");
35	        jdbc.update("DELETE FROM measurement");
36	        jdbc.update("DELETE FROM calibration_certificate");
37	        jdbc.update("DELETE FROM instrument_lock");
38	    }
39	
40	    private long createCert(String instrument, String a, String b) throws Exception {
41	        String body = mvc.perform(post("/api/certificates").contentType(MediaType.APPLICATION_JSON)
42	                        .content("""
43	                                {"instrumentId":"%s","validFrom":"2026-01-01T00:00:00Z",
44	                                 "validTo":"2028-01-01T00:00:00Z","a":"%s","b":"%s"}
45	                                """.formatted(instrument, a, b)))
46	                .andExpect(status().isCreated()).andReturn().getResponse().getContentAsString();
47	        return ((Number) com.jayway.jsonpath.JsonPath.read(body, "$.id")).longValue();
48	    }
49	
50	    private void submit(String key, String instrument, String reading, String lower,
51	                        String upper, String by) throws Exception {
52	        mvc.perform(post("/api/measurements").contentType(MediaType.APPLICATION_JSON)
53	                        .content("""
54	                                {"measurementKey":"%s","instrumentId":"%s",
55	                                 "measuredAt":"2026-06-01T00:00:00Z","reading":"%s",
56	                                 "lowerLimit":"%s","upperLimit":"%s","submittedBy":"%s"}
57	                                """.formatted(key, instrument, reading, lower, upper, by)))
58	                .andExpect(status().isCreated());
59	    }
60	
61	    @Test
62	    void validBatchReleasedAtomically() throws Exception {
63	        createCert("INS-1", "1", "0");
64	        submit("R-1", "INS-1", "1", "0", "9", "alice");
65	        submit("R-2", "INS-1", "2", "0", "9", "bob");
66	
67	        mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders
68	                        .post("/api/measurements/release")
69	                        .header("X-Actor-Id", "carol")
70	                        .contentType(MediaType.APPLICATION_JSON)
71	                        .content("{\"keys\":[\"R-1\",\"R-2\"]}"))
72	                .andExpect(status().isOk())
73	                .andExpect(jsonPath("$.batchId").isString())
74	                .andExpect(jsonPath("$.releasedBy").value("carol"))
75	                .andExpect(jsonPath("$.released[0]").value("R-1"))
76	                .andExpect(jsonPath("$.released[1]").value("R-2"));
77	
78	        mvc.perform(get("/api/measurements/{key}", "R-1"))
79	                .andExpect(jsonPath("$.status").value("RELEASED"))
80	                .andExpect(jsonPath("$.usable").value(true))
81	                .andExpect(jsonPath("$.releases[0].releasedBy").value("carol"))
82	                .andExpect(jsonPath("$.releases[0].batchId").isString());
83	
84	        mvc.perform(get("/api/measurements/usable"))
85	                .andExpect(jsonPath("$.length()").value(2));
86	        mvc.perform(get("/api/measurements/usable").param("instrumentId", "INS-1"))
87	                .andExpect(jsonPath("$.length()").value(2));
88	        mvc.perform(get("/api/measurements/usable").param("instrumentId", "INS-OTHER"))
89	                .andExpect(jsonPath("$.length()").value(0));
90	    }
91	
92	    @Test
93	    void invalidBatchRejectsWholeBatchWithItemReasonsAndNoPartialSuccess() throws Exception {
94	        createCert("INS-1", "1", "0");
95	        submit("R-OK", "INS-1", "1", "0", "9", "alice");        // 合格但提交人=放行人
96	        submit("R-FAIL", "INS-1", "100", "0", "9", "bob");      // 不合格
97	        submit("R-GOOD", "INS-1", "2", "0", "9", "bob");        // 合法可放行
98	
99	        // 放行人 alice：R-OK 触发 SAME_ACTOR；R-FAIL 触发 NOT_PASSED → 整批 409
100	        mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders
101	                        .post("/api/measurements/release")
102	                        .header("X-Actor-Id", "alice")
103	                        .contentType(MediaType.APPLICATION_JSON)
104	                        .content("{\"keys\":[\"R-OK\",\"R-FAIL\",\"R-GOOD\"]}"))
105	                .andExpect(status().isConflict())
106	                .andExpect(jsonPath("$.code").value("BATCH_REJECTED"))
107	                .andExpect(jsonPath("$.failures[?(@.key=='R-OK')].reasons[0]").value("SAME_ACTOR"))
108	                .andExpect(jsonPath("$.failures[?(@.key=='R-FAIL')].reasons[0]").value("NOT_PASSED"))
109	                .andExpect(jsonPath("$.failures.length()").value(2));
110	
111	        // 整批回滚：R-GOOD 仍为待放行，未被部分放行
