                                .header("X-Actor-Id", "carol")
                                .contentType(MediaType.APPLICATION_JSON)
                                .content("{\"items\":[{\"measurementKey\":\"M-X" + r
                                        + "\",\"revision\":1}]}"))
                        .andReturn().getResponse().getStatus();
            });
            start.countDown();
