 */
public Optional<Measurement> findLatestByKeyForUpdate(String key) {
    return jdbc.query("SELECT * FROM measurement WHERE measurement_key = ? AND is_latest = TRUE FOR UPDATE",
                    MAPPER, key)
            .stream().findFirst();
}

/**
 * 按测量键与修订号查询并加行锁（须在事务内调用），用于版本化放行时串行化状态流转。
 */
public Optional<Measurement> findByKeyAndRevisionForUpdate(String key, int revision) {
    return jdbc.query("SELECT * FROM measurement WHERE measurement_key = ? AND revision = ? FOR UPDATE",
                    MAPPER, key, revision)
            .stream().findFirst();
}

/**
 * 查询某测量键的最大修订号；键不存在时返回 0。
 */
public int maxRevision(String key) {
    Integer max = jdbc.queryForObject(
            "SELECT COALESCE(MAX(revision), 0) FROM measurement WHERE measurement_key = ?",
            Integer.class, key);
    return max == null ? 0 : max;
}

